  <div id="c0" style="${STY('var(--acc)')}top:100px;">NVIDIA FEDERAL<br>INVESTIGATION</div>
  <div id="c1" style="${STY('var(--acc2)')}top:420px;">FOREIGN TIES<br>PROBE</div>
  <div id="c2" style="${STY('var(--acc)')}top:740px;">QUARTERLY<br>EARNINGS REPORT</div>
`;

const items = [0, 1, 2].map(i => root.querySelector('#c' + i));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});

function frame(t, p, d) {
  const tf = p >= 0.55 ? d * 0.55 : t;

  // Cards Entrance with Springs
  const delays = [0.1, 1.2, 2.3];
  items.forEach((el, i) => {
    const s = spr(tf, delays[i], 0.8, 8);
    el.style.opacity = clamp(s * 2);
    const scale = lerp(0.85, 1, E_OUT(clamp(s)));
    const slide = lerp(40, 0, E_OUT(clamp(s)));
    el.style.transform = `translateY(${slide}px) scale(${scale})`;
  });

  // Connecting Lines Drawing
  const lineDelays = [0.8, 1.9];
  lines.forEach((l, i) => {
    const lp = clamp((tf - lineDelays[i]) * 2.5);
    l.el.style.strokeDashoffset = l.len * (1 - E_INOUT(lp));
  });

  // Deterministic hold for P > 0.55
  if (p >= 0.55) {
    items.forEach(el => {
      el.style.opacity = 1;
      el.style.transform = 'translateY(0px) scale(1)';
    });
    lines.forEach(l => l.el.style.strokeDashoffset = 0);
  }
}
